package kr.memorynotes;
public class PdfCaptureTitleTest{public static void main(String[] args){if(!PdfCaptureTitle.automatic(null,3,674).equals("문제 3 · 674쪽"))throw new AssertionError();if(!PdfCaptureTitle.automatic("  \n문제 제목\r\n나머지 지문",1,1).equals("문제 제목"))throw new AssertionError();StringBuilder s=new StringBuilder();for(int i=0;i<90;i++)s.append("😀");String title=PdfCaptureTitle.automatic(s.toString(),1,1);if(title.codePointCount(0,title.length())!=80||Character.isHighSurrogate(title.charAt(title.length()-1)))throw new AssertionError();System.out.println("PASS: image fallback, multiline title and Unicode-safe length");}}
